<script setup lang="ts">
import AppIcon from '../components/AppIcon.vue'
import PageHeader from '../components/PageHeader.vue'
import AppModal from '../components/AppModal.vue'
import EmptyState from '../components/EmptyState.vue'
import { onMounted, ref } from 'vue'
import { api, errorText } from '../lib/api'
interface Word { id: string; word: string; kind: string; definition: string; synonyms: string[]; antonyms: string[]; scenario: string; pitfalls: string; example: string; favorite: boolean; mastered: boolean }
const items = ref<Word[]>([]), recommended = ref<Word[]>([]), total = ref(0), page = ref(1), q = ref(''), state = ref(''), error = ref(''), open = ref(false), editing = ref(''), busy = ref(false), loading = ref(true)
const initial = () => ({ word: '', kind: '成语', definition: '', synonyms: '', antonyms: '', scenario: '', pitfalls: '', example: '' })
const form = ref(initial())
const split = (value: string) => value.split(/[，,、\n]/).map(x => x.trim()).filter(Boolean)
async function load(reset = false) { if (reset) page.value = 1; loading.value = true; try { const { data } = await api.get('/idioms', { params: { q: q.value, page: page.value, favorite: state.value === 'favorite' ? true : undefined, mastered: state.value === 'mastered' ? true : state.value === 'learning' ? false : undefined } }); items.value = data.items; total.value = data.total; recommended.value = (await api.get('/idioms/today')).data; error.value = '' } catch (e) { error.value = errorText(e) } finally { loading.value = false } }
function edit(word?: Word) { editing.value = word?.id || ''; form.value = word ? { ...word, synonyms: word.synonyms.join('，'), antonyms: word.antonyms.join('，') } : initial(); open.value = true }
async function save() { busy.value = true; try { const body = { ...form.value, synonyms: split(form.value.synonyms), antonyms: split(form.value.antonyms) }; if (editing.value) await api.put('/idioms/' + editing.value, body); else await api.post('/idioms', body); open.value = false; await load() } catch (e) { error.value = errorText(e) } finally { busy.value = false } }
async function toggle(word: Word, key: 'favorite' | 'mastered') { try { await api.patch('/idioms/' + word.id, { [key]: !word[key] }); await load() } catch (e) { error.value = errorText(e) } }
async function remove(id: string) { if (confirm('删除这条词语积累？')) try { await api.delete('/idioms/' + id); await load() } catch (e) { error.value = errorText(e) } }
onMounted(() => load())
</script>
<template><PageHeader title="成语与词语"><template #description><p class="muted">共 {{ total }} 条词语</p></template><button class="button" @click="edit()"><AppIcon name="plus" :size="17" />添加词语</button></PageHeader><section v-if="recommended.length" class="panel recommendation"><span class="eyebrow">今日推荐</span><h2>{{ recommended[0]?.word }}</h2><p class="reading">{{ recommended[0]?.definition }}</p></section><form class="toolbar" @submit.prevent="load(true)"><input v-model="q" placeholder="查找词语或释义" aria-label="查找词语"><select v-model="state" @change="load(true)" aria-label="掌握状态"><option value="">全部词语</option><option value="favorite">我的收藏</option><option value="learning">尚未掌握</option><option value="mastered">已掌握</option></select><button class="button secondary">查找</button></form><p v-if="error" class="error" role="alert">{{ error }}</p><p v-if="loading" class="loading-state" role="status">正在读取词语…</p><EmptyState v-else-if="!items.length && !error" :title="q || state ? '没有找到相关词语' : '词语库为空'" :description="q || state ? '试试其他关键词，或清除掌握状态筛选。' : '添加词语、释义和使用示例。'" icon="words"><button v-if="q || state" class="button secondary" @click="q = ''; state = ''; load(true)">清除筛选</button><button v-else class="button" @click="edit()">添加词语</button></EmptyState><section v-for="word in items" :key="word.id" class="panel section-gap word-card"><div class="panel-heading"><div class="actions"><h2>{{ word.word }}</h2><span class="tag">{{ word.kind }}</span><span v-if="word.mastered" class="tag neutral">已掌握</span></div><div class="actions"><button class="text-button" :aria-pressed="word.favorite" @click="toggle(word,'favorite')"><AppIcon name="star" :size="15" :class="{ 'is-favorite': word.favorite }" />{{ word.favorite ? '已收藏' : '收藏' }}</button><button class="text-button" @click="edit(word)">编辑</button></div></div><p class="reading">{{ word.definition }}</p><details><summary>近反义词、场景与示例</summary><p class="reading">近义词：{{ word.synonyms.join('、') || '未填写' }}<br>反义词：{{ word.antonyms.join('、') || '未填写' }}</p><h3>使用场景</h3><p class="reading">{{ word.scenario || '未填写' }}</p><h3>易错点</h3><p class="reading">{{ word.pitfalls || '未填写' }}</p><h3>示例</h3><p class="reading">{{ word.example || '未填写' }}</p></details><div class="actions"><button class="button secondary" @click="toggle(word,'mastered')">{{ word.mastered ? '标为未掌握' : '标为已掌握' }}</button><button class="text-button danger" @click="remove(word.id)">删除</button></div></section><div v-if="total > 20" class="pagination"><button class="button secondary" :disabled="page === 1" @click="page--; load()">上一页</button><span>{{ page }} / {{ Math.ceil(total / 20) }}</span><button class="button secondary" :disabled="page * 20 >= total" @click="page++; load()">下一页</button></div><AppModal v-model:open="open" :title="editing ? '编辑词语' : '添加词语'" :busy="busy"><form @submit.prevent="save"><h2>{{ editing ? '编辑词语' : '添加词语' }}</h2><div class="form-grid"><label>词语<input v-model="form.word" required maxlength="100"></label><label>类别<select v-model="form.kind"><option>成语</option><option>词语</option></select></label></div><label>释义<textarea v-model="form.definition" required rows="3" maxlength="10000"></textarea></label><div class="form-grid"><label>近义词（逗号分隔）<input v-model="form.synonyms"></label><label>反义词（逗号分隔）<input v-model="form.antonyms"></label></div><label>使用场景<textarea v-model="form.scenario" maxlength="5000"></textarea></label><label>易错点<textarea v-model="form.pitfalls" maxlength="5000"></textarea></label><label>示例<textarea v-model="form.example" maxlength="5000"></textarea></label><p v-if="error" class="error">{{ error }}</p><div class="actions"><button type="button" class="button secondary" :disabled="busy" @click="open = false">取消</button><button class="button" :disabled="busy">保存词语</button></div></form></AppModal></template>
